from base64 import b64encode


def get_basic_access_token(username="Nemuadmin", password="Nokia@123"):
    """
    Generate a Basic Access Token for HTTP Basic Authentication.

    :param username: The username for authentication, defaults to Nemuadmin
    :param password: The password for authentication, defaults to Nokia@123

    :return: A Base64 encoded string for Basic Authentication
    """
    basic_auth_token = f"{username}:{password}"
    return b64encode(basic_auth_token.encode(encoding="utf-8")).decode()
